-- V3 BLOCK G — FINANZAS
CREATE TABLE IF NOT EXISTS v3_invoices (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,invoice_number VARCHAR(40) NOT NULL,quote_id INT NULL,job_id INT NULL,client_id INT NULL,issue_date DATE NOT NULL,due_date DATE NULL,status ENUM('borrador','emitida','pagada','vencida','anulada') NOT NULL DEFAULT 'borrador',subtotal DECIMAL(12,2) NOT NULL DEFAULT 0,tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL DEFAULT 0,notes TEXT NULL,created_by INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_v3_invoice_number(invoice_number),KEY idx_v3_invoice_client(client_id),KEY idx_v3_invoice_job(job_id),KEY idx_v3_invoice_quote(quote_id),CONSTRAINT fk_v3_invoice_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS v3_invoice_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,invoice_id BIGINT UNSIGNED NOT NULL,description VARCHAR(255) NOT NULL,quantity DECIMAL(10,2) NOT NULL DEFAULT 1,unit_price DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL DEFAULT 0,PRIMARY KEY(id),KEY idx_v3_invoice_items(invoice_id),CONSTRAINT fk_v3_invoice_items_invoice FOREIGN KEY(invoice_id) REFERENCES v3_invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS v3_payments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,invoice_id BIGINT UNSIGNED NULL,quote_id INT NULL,job_id INT NULL,client_id INT NULL,amount DECIMAL(12,2) NOT NULL,payment_date DATE NOT NULL,method ENUM('efectivo','transferencia','tarjeta','mercadopago','otro') NOT NULL DEFAULT 'transferencia',reference VARCHAR(120) NULL,notes TEXT NULL,created_by INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_v3_payment_date(payment_date),KEY idx_v3_payment_client(client_id),CONSTRAINT fk_v3_payment_invoice FOREIGN KEY(invoice_id) REFERENCES v3_invoices(id) ON DELETE SET NULL,CONSTRAINT fk_v3_payment_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS v3_expenses (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,expense_date DATE NOT NULL,category VARCHAR(80) NOT NULL,description VARCHAR(255) NOT NULL,amount DECIMAL(12,2) NOT NULL,supplier VARCHAR(190) NULL,job_id INT NULL,status ENUM('registrado','anulado') NOT NULL DEFAULT 'registrado',created_by INT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_v3_expense_date(expense_date),KEY idx_v3_expense_job(job_id),CONSTRAINT fk_v3_expense_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS v3_finance_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,entity_type VARCHAR(40) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(60) NOT NULL,actor_user_id INT NULL,metadata JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_v3_finance_events_entity(entity_type,entity_id,created_at),CONSTRAINT fk_v3_finance_events_user FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE v3_system ADD COLUMN IF NOT EXISTS finance_enabled TINYINT(1) NOT NULL DEFAULT 1;
ALTER TABLE business_settings ADD COLUMN IF NOT EXISTS invoice_prefix VARCHAR(20) NOT NULL DEFAULT 'FC-';
ALTER TABLE business_settings ADD COLUMN IF NOT EXISTS invoice_next_number INT UNSIGNED NOT NULL DEFAULT 1;